<?php $page_title='Add Doctor';require_once __DIR__.'/../includes/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("INSERT INTO doctors(name,specialization,phone,email,license_no,status) VALUES(?,?,?,?,?,?)")->execute([$_POST['name'],$_POST['specialization'],$_POST['phone'],$_POST['email'],$_POST['license_no'],'active']);header('Location:index.php');exit;}?><h2>Add Doctor</h2><div class="card p-4 mt-3"><form method="post"><div class="row g-3"><?php foreach(['name'=>'Doctor Name','specialization'=>'Specialization','phone'=>'Phone','email'=>'Email','license_no'=>'License No.'] as $n=>$l):?><div class="col-md-6"><label><?=$l?></label><input name="<?=$n?>" class="form-control" required></div><?php endforeach;?></div><button class="btn btn-primary mt-3">Save Doctor</button></form></div><?php require_once __DIR__.'/../includes/footer.php';?>